class FeatureStoreClient:
    """Redis-backed feature store client with caching."""
    
    def __init__(self, redis_url: str, ttl: int = 3600):
        self.redis_client = redis.Redis.from_url(redis_url, decode_responses=True)
        self.ttl = ttl
        self.cache_hits = 0
        self.cache_misses = 0
    
    def get_features(self, node_id: str, timestamp: datetime) -> Optional[Dict]:
        """Retrieve cached features for a node at a specific time."""
        cache_key = self._generate_key(node_id, timestamp)
        try:
            data = self.redis_client.get(cache_key)
            if data:
                self.cache_hits += 1
                return pickle.loads(data.encode('latin1'))
        except Exception as e:
            logger.warning(f"Cache retrieval failed: {e}")
        self.cache_misses += 1
        return None
    
    def set_features(self, node_id: str, timestamp: datetime, features: Dict) -> bool:
        """Cache features for a node at a specific time."""
        cache_key = self._generate_key(node_id, timestamp)
        try:
            serialized = pickle.dumps(features).decode('latin1')
            return self.redis_client.setex(cache_key, self.ttl, serialized)
        except Exception as e:
            logger.error(f"Cache set failed: {e}")
            return False
    
    def _generate_key(self, node_id: str, timestamp: datetime) -> str:
        """Generate deterministic cache key."""
        time_str = timestamp.strftime('%Y%m%d%H%M%S')
        return f"features:{node_id}:{time_str}"
    
    def get_stats(self) -> Dict:
        """Return cache statistics."""
        return {
            'hits': self.cache_hits,
            'misses': self.cache_misses,
            'hit_rate': self.cache_hits / (self.cache_hits + self.cache_misses) if (self.cache_hits + self.cache_misses) > 0 else 0
        }


class DataLoader:
    """Robust data loading and preprocessing pipeline."""
    
    def __init__(self, config: DataConfig):
        self.config = config
        self.feature_store = FeatureStoreClient(config.feature_store, config.cache_ttl)
        self.logger = logging.getLogger(f"{__name__}.DataLoader")
    
    def load_data(self) -> Tuple[pd.DataFrame, pd.Series]:
        """
        Load and preprocess training data.
        
        Returns:
            Tuple of (features DataFrame, target Series)
        """
        try:
            self.logger.info(f"Loading data from {self.config.source_path}")
            
            # Determine file type and load accordingly
            file_path = Path(self.config.source_path)
            if file_path.suffix == '.parquet':
                df = pd.read_parquet(file_path)
            elif file_path.suffix == '.csv':
                df = pd.read_csv(file_path, parse_dates=['timestamp'])
            elif file_path.suffix == '.json':
                df = pd.read_json(file_path)
            else:
                raise ValueError(f"Unsupported file format: {file_path.suffix}")
            
            self.logger.info(f"Loaded {len(df)} records with {len(df.columns)} columns")
            
            # Validate required columns
            required_cols = [self.config.target_column] + self.config.feature_columns
            missing_cols = [col for col in required_cols if col not in df.columns]
            if missing_cols:
                raise ValueError(f"Missing required columns: {missing_cols}")
            
            # Feature selection
            if self.config.feature_columns:
                features = df[self.config.feature_columns].copy()
            else:
                features = df.drop(columns=[self.config.target_column] + self.config.exclude_columns, errors='ignore').copy()
            
            target = df[self.config.target_column].copy()
            
            # Data quality checks
            self._validate_data(features, target)
            
            # Handle missing values
            features = self._handle_missing_values(features)
            
            # Feature engineering
            features = self._engineer_features(features)
            
            self.logger.info(f"Preprocessed data: {features.shape[0]} samples, {features.shape[1]} features")
            return features, target
            
        except Exception as e:
            self.logger.error(f"Data loading failed: {e}")
            raise
    
    def _validate_data(self, features: pd.DataFrame, target: pd.Series) -> None:
        """Validate data quality and integrity."""
        if len(features) != len(target):
            raise ValueError(f"Feature/target length mismatch: {len(features)} vs {len(target)}")
        
        if target.isnull().any():
            self.logger.warning(f"Found {target.isnull().sum()} null values in target")
            target.fillna(target.median(), inplace=True)
        
        if features.isnull().any().any():
            null_counts = features.isnull().sum()
            self.logger.warning(f"Found null values in features: {null_counts[null_counts > 0].to_dict()}")
    
    def _handle_missing_values(self, features: pd.DataFrame) -> pd.DataFrame:
        """Handle missing values with appropriate strategies."""
        numeric_cols = features.select_dtypes(include=[np.number]).columns
        categorical_cols = features.select_dtypes(include=['object', 'category']).columns
        
        # Numeric: fill with median
        if len(numeric_cols) > 0:
            features[numeric_cols] = features[numeric_cols].fillna(features[numeric_cols].median())
        
        # Categorical: fill with mode
        if len(categorical_cols) > 0:
            for col in categorical_cols:
                features[col] = features[col].fillna(features[col].mode()[0] if not features[col].mode().empty else 'unknown')
        
        return features
    
    def _engineer_features(self, features: pd.DataFrame) -> pd.DataFrame:
        """Create derived features for improved prediction."""
        engineered = features.copy()
        
        # Time-based features (if timestamp exists)
        if 'timestamp' in engineered.columns:
            ts = pd.to_datetime(engineered['timestamp'])
            engineered['hour'] = ts.dt.hour
            engineered['day_of_week'] = ts.dt.dayofweek
            engineered['day_of_month'] = ts.dt.day
            engineered['month'] = ts.dt.month
            engineered['is_weekend'] = (ts.dt.dayofweek >= 5).astype(int)
            engineered = engineered.drop(columns=['timestamp'])
        
        # Interaction features for numeric columns
        numeric_cols = engineered.select_dtypes(include=[np.number]).columns
        if len(numeric_cols) >= 2:
            # Rolling statistics if we have a sequence indicator
            if 'sequence' in engineered.columns:
                for col in numeric_cols[:3]:  # Limit to first 3 for performance
                    engineered[f'{col}_rolling_mean'] = engineered[col].rolling(window=5, min_periods=1).mean()
                    engineered[f'{col}_rolling_std'] = engineered[col].rolling(window=5, min_periods=1).std()
        
        return engineered


