class ModelFactory:
    """Factory for creating model instances with consistent interface."""
    
    @staticmethod
    def create_model(model_type: str, **params) -> Any:
        """Create a model instance based on type and parameters."""
        params.setdefault('random_state', 42)
        
        if model_type == 'xgboost':
            params.setdefault('n_estimators', 1000)
            params.setdefault('learning_rate', 0.01)
            params.setdefault('max_depth', 6)
            params.setdefault('subsample', 0.8)
            params.setdefault('colsample_bytree', 0.8)
            params.setdefault('n_jobs', -1)
            return XGBRegressor(**params)
        
        elif model_type == 'lightgbm':
            params.setdefault('n_estimators', 1000)
            params.setdefault('learning_rate', 0.01)
            params.setdefault('num_leaves', 31)
            params.setdefault('n_jobs', -1)
            return LGBMRegressor(**params)
        
        elif model_type == 'gradient_boosting':
            params.setdefault('n_estimators', 1000)
            params.setdefault('learning_rate', 0.01)
            params.setdefault('max_depth', 6)
            return GradientBoostingRegressor(**params)
        
        elif model_type == 'random_forest':
            params.setdefault('n_estimators', 500)
            params.setdefault('max_depth', 20)
            params.setdefault('n_jobs', -1)
            return RandomForestRegressor(**params)
        
        else:
            raise ValueError(f"Unsupported model type: {model_type}")


