class HyperparameterTuner:
    """Optuna-based hyperparameter optimization with pruning and distributed support."""
    
    def __init__(self, config: TuningConfig, model_type: str, data: Tuple[pd.DataFrame, pd.Series]):
        self.config = config
        self.model_type = model_type
        self.X, self.y = data
        self.logger = logging.getLogger(f"{__name__}.HyperparameterTuner")
        
        # Setup Optuna storage for distributed tuning
        self.storage = os.getenv('OPTUNA_STORAGE', 'sqlite:///optuna.db')
        self.study_name = f"swarm_tuning_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        
    def _get_param_space(self, trial: optuna.Trial) -> Dict:
        """Define hyperparameter search space based on model type."""
        if self.model_type == 'xgboost':
            return {
                'n_estimators': trial.suggest_int('n_estimators', 100, 2000, step=100),
                'learning_rate': trial.suggest_float('learning_rate', 0.001, 0.1, log=True),
                'max_depth': trial.suggest_int('max_depth', 3, 12),
                'min_child_weight': trial.suggest_int('min_child_weight', 1, 10),
                'subsample': trial.suggest_float('subsample', 0.5, 1.0),
                'colsample_bytree': trial.suggest_float('colsample_bytree', 0.5, 1.0),
                'gamma': trial.suggest_float('gamma', 0, 5),
                'reg_alpha': trial.suggest_float('reg_alpha', 1e-8, 10, log=True),
                'reg_lambda': trial.suggest_float('reg_lambda', 1e-8, 10, log=True)
            }
        elif self.model_type == 'lightgbm':
            return {
                'n_estimators': trial.suggest_int('n_estimators', 100, 2000, step=100),
                'learning_rate': trial.suggest_float('learning_rate', 0.001, 0.1, log=True),
                'num_leaves': trial.suggest_int('num_leaves', 10, 100),
                'max_depth': trial.suggest_int('max_depth', 3, 12),
                'min_child_samples': trial.suggest_int('min_child_samples', 5, 50),
                'subsample': trial.suggest_float('subsample', 0.5, 1.0),
                'colsample_bytree': trial.suggest_float('colsample_bytree', 0.5, 1.0),
                'reg_alpha': trial.suggest_float('reg_alpha', 1e-8, 10, log=True),
                'reg_lambda': trial.suggest_float('reg_lambda', 1e-8, 10, log=True)
            }
        elif self.model_type == 'gradient_boosting':
            return {
                'n_estimators': trial.suggest_int('n_estimators', 100, 1000, step=50),
                'learning_rate': trial.suggest_float('learning_rate', 0.001, 0.1, log=True),
                'max_depth': trial.suggest_int('max_depth', 3, 10),
                'min_samples_split': trial.suggest_int('min_samples_split', 2, 20),
                'min_samples_leaf': trial.suggest_int('min_samples_leaf', 1, 20),
                'subsample': trial.suggest_float('subsample', 0.5, 1.0),
                'max_features': trial.suggest_float('max_features', 0.1, 1.0)
            }
        elif self.model_type == 'random_forest':
            return {
                'n_estimators': trial.suggest_int('n_estimators', 100, 1000, step=50),
                'max_depth': trial.suggest_int('max_depth', 5, 30),
                'min_samples_split': trial.suggest_int('min_samples_split', 2, 20),
                'min_samples_leaf': trial.suggest_int('min_samples_leaf', 1, 20),
                'max_features': trial.suggest_float('max_features', 0.1, 1.0),
                'bootstrap': trial.suggest_categorical('bootstrap', [True, False])
            }
        else:
            raise ValueError(f"Unsupported model type for tuning: {self.model_type}")
    
    def _objective(self, trial: optuna.Trial) -> float:
        """Objective function for Optuna optimization."""
        try:
            params = self._get_param_space(trial)
            params['random_state'] = 42
            
            # Create model with trial parameters
            model = ModelFactory.create_model(self.model_type, **params)
            
            # Time series cross-validation
            tscv = TimeSeriesSplit(n_splits=5)
            scores = []
            
            for fold_idx, (train_idx, val_idx) in enumerate(tscv.split(self.X)):
                X_train, X_val = self.X.iloc[train_idx], self.X.iloc[val_idx]
                y_train, y_val = self.y.iloc[train_idx], self.y.iloc[val_idx]
                
                # Train model
                model.fit(X_train, y_train)
                
                # Predict and evaluate
                y_pred = model.predict(X_val)
                score = mean_absolute_error(y_val, y_pred)
                scores.append(score)
                
                # Pruning check
                if trial.should_prune():
                    raise optuna.TrialPruned()
            
            # Return negative MAE (Optuna minimizes)
            return -np.mean(scores)
            
        except Exception as e:
            self.logger.error(f"Trial failed: {e}")
            return float('inf')
    
    def tune(self) -> optuna.Study:
        """Execute hyperparameter tuning."""
        self.logger.info(f"Starting hyperparameter tuning with {self.config.n_trials} trials")
        
        # Create study with TPE sampler and median pruner
        sampler = TPESampler(
            n_startup_trials=self.config.n_startup_trials,
            n_ei_candidates=self.config.n_ei_candidates,
            seed=42
        )
        pruner = MedianPruner(
            n_startup_trials=self.config.n_startup_trials,
            n_warmup_steps=self.config.prune_interval,
            interval_steps=self.config.prune_interval
        )
        
        study = optuna.create_study(
            study_name=self.study_name,
            storage=self.storage,
            load_if_exists=True,
            direction='minimize',
            sampler=sampler,
            pruner=pruner
        )
        
        # Execute optimization
        study.optimize(
            self._objective,
            n_trials=self.config.n_trials,
            timeout=self.config.timeout_seconds,
            show_progress_bar=True
        )
        
        self.logger.info(f"Tuning completed. Best MAE: {-study.best_value:.4f}")
        self.logger.info(f"Best parameters: {study.best_params}")
        
        return study


