class ModelRegistry:
    """MLflow-based model registry with versioning and stage management."""
    
    def __init__(self, config: RegistryConfig):
        self.config = config
        mlflow.set_tracking_uri(config.tracking_uri)
        mlflow.set_experiment(config.experiment_name)
        self.client = MlflowClient(tracking_uri=config.tracking_uri)
        self.logger = logging.getLogger(f"{__name__}.ModelRegistry")
        
        # Ensure model exists in registry
        self._ensure_model_registered()
    
    def _ensure_model_registered(self) -> None:
        """Create model in registry if it doesn't exist."""
        try:
            self.client.get_registered_model(self.config.registry_model_name)
        except Exception:
            self.logger.info(f"Creating new model: {self.config.registry_model_name}")
            self.client.create_registered_model(
                self.config.registry_model_name,
                tags={'purpose': 'swarm_performance_prediction'}
            )
    
    def log_model(self, model: Any, params: Dict, metrics: Dict, artifacts: Dict[str, str]) -> str:
        """Log model with parameters, metrics, and artifacts to MLflow."""
        with mlflow.start_run(run_name=f"training_{datetime.now().strftime('%Y%m%d_%H%M%S')}") as run:
            # Log parameters
            for key, value in params.items():
                mlflow.log_param(key, value)
            
            # Log metrics
            for key, value in metrics.items():
                mlflow.log_metric(key, value)
            
            # Log artifacts
            for name, path in artifacts.items():
                mlflow.log_artifact(path, artifact_path=name)
            
            # Log model
            mlflow.sklearn.log_model(
                sk_model=model,
                artifact_path="model",
                registered_model_name=self.config.registry_model_name,
                signature=None,
                input_example=self._get_input_example()
            )
            
            run_id = run.info.run_id
            self.logger.info(f"Model logged with run_id: {run_id}")
            return run_id
    
    def _get_input_example(self) -> Optional[pd.DataFrame]:
        """Generate input example for model signature."""
        # This would be populated from actual data in production
        return None
    
    def transition_stage(self, run_id: str, stage: str) -> None:
        """Transition model to specified stage."""
        if stage not in self.config.stage_transitions:
            raise ValueError(f"Invalid stage: {stage}")
        
        try:
            # Get model version
            versions = self.client.get_latest_versions(self.config.registry_model_name)
            target_version = None
            
            for version in versions:
                if version.run_id == run_id:
                    target_version = version
                    break
            
            if not target_version:
                # Find version by run_id
                all_versions = self.client.search_model_versions(f"name='{self.config.registry_model_name}'")
                for version in all_versions:
                    if version.run_id == run_id:
                        target_version = version
                        break
            
            if not target_version:
                raise ValueError(f"No model version found for run_id: {run_id}")
            
            # Transition stage
            self.client.transition_model_version_stage(
                name=self.config.registry_model_name,
                version=target_version.version,
                stage=stage,
                archive_existing_versions=True
            )
            
            self.logger.info(f"Model version {target_version.version} transitioned to {stage}")
            
            # Cleanup old versions if exceeding max
            self._cleanup_old_versions(stage)
            
        except Exception as e:
            self.logger.error(f"Stage transition failed: {e}")
            raise
    
    def _cleanup_old_versions(self, stage: str) -> None:
        """Archive old versions in a stage beyond the maximum."""
        versions = self.client.search_model_versions(
            f"name='{self.config.registry_model_name}' AND stage='{stage}'"
        )
        
        if len(versions) > self.config.max_models_per_stage:
            # Sort by version number and archive oldest
            versions.sort(key=lambda v: v.version)
            to_archive = versions[:-self.config.max_models_per_stage]
            
            for version in to_archive:
                self.client.transition_model_version_stage(
                    name=self.config.registry_model_name,
                    version=version.version,
                    stage="Archived"
                )
                self.logger.info(f"Archived model version {version.version}")
    
    def load_model(self, stage: str = "Production") -> Any:
        """Load model from specified stage."""
        try:
            model_uri = f"models:/{self.config.registry_model_name}/{stage}"
            model = mlflow.sklearn.load_model(model_uri)
            self.logger.info(f"Loaded model from {stage} stage")
            return model
        except Exception as e:
            self.logger.error(f"Model loading failed: {e}")
            raise
    
    def get_model_versions(self) -> List[Dict]:
        """Get all versions of the registered model."""
        versions = self.client.search_model_versions(f"name='{self.config.registry_model_name}'")
        return [
            {
                'version': v.version,
                'stage': v.current_stage,
                'run_id': v.run_id,
                'status': v.status,
                'created_at': v.creation_timestamp
            }
            for v in versions
        ]


