class TrainingPipeline:
    """Main orchestrator for the training pipeline."""
    
    def __init__(self, config_path: str):
        self.config = self._load_config(config_path)
        self.logger = logging.getLogger(f"{__name__}.TrainingPipeline")
        self._setup_logging()
        
        # Initialize components
        self.data_loader = DataLoader(self.config.data)
        self.registry = ModelRegistry(self.config.registry)
        
        # Reproducibility
        self.reproducibility_hash = self._generate_reproducibility_hash()
    
    def _load_config(self, config_path: str) -> PipelineConfig:
        """Load and validate configuration from YAML file."""
        try:
            with open(config_path, 'r') as f:
                config_dict = yaml.safe_load(f)
            
            config = PipelineConfig(**config_dict)
            self.logger.info(f"Configuration loaded from {config_path}")
            return config
            
        except ValidationError as e:
            self.logger.error(f"Configuration validation failed: {e}")
            raise
        except Exception as e:
            self.logger.error(f"Configuration loading failed: {e}")
            raise
    
    def _setup_logging(self) -> None:
        """Configure logging based on config."""
        log_level = getattr(logging, self.config.log_level)
        logging.getLogger().setLevel(log_level)
    
    def _generate_reproducibility_hash(self) -> str:
        """Generate hash for reproducibility tracking."""
        config_str = json.dumps(self.config.dict(), sort_keys=True, default=str)
        return hashlib.sha256(config_str.encode()).hexdigest()[:16]
    
    def run(self) -> Dict:
        """Execute the complete training pipeline."""
        start_time = time.time()
        self.logger.info(f"Starting training pipeline (reproducibility: {self.reproducibility_hash})")
        
        try:
            # 1. Load and preprocess data
            X, y = self.data_loader.load_data()
            self.logger.info(f"Data loaded: {X.shape[0]} samples, {X.shape[1]} features")
            
            # 2. Hyperparameter tuning (if enabled)
            best_params = {}
            if self.config.tuning.enabled:
                tuner = HyperparameterTuner(self.config.tuning, self.config.model.model_type, (X, y))
                study = tuner.tune()
                best_params = study.best_params
                self.logger.info(f"Best hyperparameters: {best_params}")
            else:
                # Use default parameters
                best_params = {}
            
            # 3. Train final model with best parameters
            model = self._train_final_model(X, y, best_params)
            
            # 4. Evaluate model
            metrics = self._evaluate_model(model, X, y)
            
            # 5. Register model
            run_id = self._register_model(model, best_params, metrics)
            
            # 6. Transition to staging
            self.registry.transition_stage(run_id, "Staging")
            
            # 7. Save artifacts
            artifacts = self._save_artifacts(model, metrics, best_params)
            
            elapsed_time = time.time() - start_time
            self.logger.info(f"Training pipeline completed in {elapsed_time:.2f} seconds")
            
            return {
                'status': 'success',
                'run_id': run_id,
                'metrics': metrics,
                'best_params': best_params,
                'model_path': artifacts['model_path'],
                'elapsed_time': elapsed_time,
                'reproducibility_hash': self.reproducibility_hash
            }
            
        except Exception as e:
            self.logger.error(f"Training pipeline failed: {e}")
            return {
                'status': 'failed',
                'error': str(e),
                'elapsed_time': time.time() - start_time
            }
    
    def _train_final_model(self, X: pd.DataFrame, y: pd.Series, params: Dict) -> Any:
        """Train final model with best parameters on full dataset."""
        self.logger.info("Training final model on full dataset")
        
        # Merge default and tuned parameters
        model_params = params.copy()
        model_params['random_state'] = self.config.model.random_state
        
        # Create and train model
        model = ModelFactory.create_model(self.config.model.model_type, **model_params)
        model.fit(X, y)
        
        self.logger.info("Final model training completed")
        return model
    
    def _evaluate_model(self, model: Any, X: pd.DataFrame, y: pd.Series) -> Dict:
        """Comprehensive model evaluation with multiple metrics."""
        self.logger.info("Evaluating model performance")
        
        # Time series cross-validation
        tscv = TimeSeriesSplit(n_splits=self.config.data.n_splits)
        cv_scores = {
            'mae': [],
            'rmse': [],
            'r2': []
        }
        
        for train_idx, val_idx in tscv.split(X):
            X_train, X_val = X.iloc[train_idx], X.iloc[val_idx]
            y_train, y_val = y.iloc[train_idx], y.iloc[val_idx]
            
            # Train on fold
            fold_model = ModelFactory.create_model(
                self.config.model.model_type,
                random_state=self.config.model.random_state
            )
            fold_model.fit(X_train, y_train)
            
            # Evaluate
            y_pred = fold_model.predict(X_val)
            cv_scores['mae'].append(mean_absolute_error(y_val, y_pred))
            cv_scores['rmse'].append(np.sqrt(mean_squared_error(y_val, y_pred)))
            cv_scores['r2'].append(r2_score(y_val, y_pred))
        
        # Final predictions on full data
        y_pred = model.predict(X)
        
        metrics = {
            'train_mae': mean_absolute_error(y, y_pred),
            'train_rmse': np.sqrt(mean_squared_error(y, y_pred)),
            'train_r2': r2_score(y, y_pred),
            'cv_mae_mean': np.mean(cv_scores['mae']),
            'cv_mae_std': np.std(cv_scores['mae']),
            'cv_rmse_mean': np.mean(cv_scores['rmse']),
            'cv_rmse_std': np.std(cv_scores['rmse']),
            'cv_r2_mean': np.mean(cv_scores['r2']),
            'cv_r2_std': np.std(cv_scores['r2'])
        }
        
        self.logger.info(f"Model metrics: {metrics}")
        return metrics
    
    def _register_model(self, model: Any, params: Dict, metrics: Dict) -> str:
        """Register model with MLflow."""
        self.logger.info("Registering model with MLflow")
        
        # Prepare artifacts
        artifacts = {
            'metrics': self._save_metrics_json(metrics),
            'params': self._save_params_json(params)
        }
        
        # Log model
        run_id = self.registry.log_model(model, params, metrics, artifacts)
        
        self.logger.info(f"Model registered with run_id: {run_id}")
        return run_id
    
    def _save_metrics_json(self, metrics: Dict) -> str:
        """Save metrics to temporary JSON file."""
        path = '/tmp/metrics.json'
        with open(path, 'w') as f:
            json.dump(metrics, f, indent=2)
        return path
    
    def _save_params_json(self, params: Dict) -> str:
        """Save parameters to temporary JSON file."""
        path = '/tmp/params.json'
        with open(path, 'w') as f:
            json.dump(params, f, indent=2)
        return path
    
    def _save_artifacts(self, model: Any, metrics: Dict, params: Dict) -> Dict:
        """Save model artifacts to disk."""
        output_dir = Path(self.config.output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        
        # Save model
        model_path = output_dir / f"model_{timestamp}.joblib"
        joblib.dump(model, model_path)
        
        # Save metrics
        metrics_path = output_dir / f"metrics_{timestamp}.json"
        with open(metrics_path, 'w') as f:
            json.dump(metrics, f, indent=2)
        
        # Save params
        params_path = output_dir / f"params_{timestamp}.json"
        with open(params_path, 'w') as f:
            json.dump(params, f, indent=2)
        
        # Save reproducibility hash
        hash_path = output_dir / f"reproducibility_{timestamp}.txt"
        with open(hash_path, 'w') as f:
            f.write(self.reproducibility_hash)
        
        return {
            'model_path': str(model_path),
            'metrics_path': str(metrics_path),
            'params_path': str(params_path),
            'hash_path': str(hash_path)
        }


# ============================================================================
# CLI Entry Point
# ============================================================================

def main():
    """CLI entry point for training pipeline."""
    import argparse
    
    parser = argparse.ArgumentParser(description='Swarm OS Training Pipeline')
    parser.add_argument('--config', required=True, help='Path to configuration YAML file')
    parser.add_argument('--dry-run', action='store_true', help='Validate configuration without training')
    
    args = parser.parse_args()
    
    if args.dry_run:
        # Validate configuration only
        try:
            with open(args.config, 'r') as f:
                config_dict = yaml.safe_load(f)
            config = PipelineConfig(**config_dict)
            print(f"Configuration valid. Reproducibility hash: {hashlib.sha256(json.dumps(config.dict(), sort_keys=True, default=str).encode()).hexdigest()[:16]}")
            return 0
        except Exception as e:
            print(f"Configuration validation failed: {e}")
            return 1
    
    # Run pipeline
    pipeline = TrainingPipeline(args.config)
    result = pipeline.run()
    
    if result['status'] == 'success':
        print(json.dumps(result, indent=2, default=str))
        return 0
    else:
        print(f"Pipeline failed: {result.get('error', 'Unknown error')}")
        return 1


if __name__ == '__main__':
    exit(main())